import { Ionicons } from "@expo/vector-icons";
import * as Print from "expo-print";
import { router, useLocalSearchParams } from "expo-router";
import * as Sharing from "expo-sharing";
import { useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import QRCode from "react-native-qrcode-svg";
import { useTheme, type Theme } from "../../theme/theme";

import api from "../../services/api";

//  PEGA AQUÍ TU TEXTO BASE64 (Solo el texto, sin comillas extras)
const LOGO_BASE64 =
  "data:image/png;base64,";

// Logo para la marca de agua central (el nuevo)
const LOGO_MARCA_AGUA_BASE64 =
  "data:image/jpeg;base64,";

interface ItemReceta {
  id_PK: number;
  medicamento: string | null;
  presentacion: string | null;
  dosis: string | null;
  frecuencia: string | null;
  duracion: string | null;
  cantidad: number | null;
  instrucciones: string | null;
  via_administracion: string | null;
}

interface RecetaDetalle {
  id_PK: number;
  estado: string | null;
  creado_en: string;
  paciente: string | null;
  doctor: string | null;
  codigo_qr?: string | null;
  especialidad?: string | null;
  numero_licencia?: string | null;
  signos_vitales?: any | null;
  items: ItemReceta[];
  indicaciones_generales?: string | null; // 👈 AGREGAR
}

export default function RecetaQRScreen() {
  const c = useTheme();
  const styles = useMemo(() => createStyles(c), [c]);
  const params = useLocalSearchParams<{
    recetaId: string;
    paciente: string;
    doctor: string;
    fecha: string;
    medicamentos: string;
    estado: string;
  }>();

  const [generandoPDF, setGenerandoPDF] = useState(false);
  const [error, setError] = useState("");
  const [cargando, setCargando] = useState(true);
  const [receta, setReceta] = useState<RecetaDetalle | null>(null);

  const recetaId = Number(params.recetaId || 0);
  const paciente = params.paciente || "Paciente";
  const doctor = params.doctor || "Médico";
  const fecha = params.fecha || "";
  const estado = params.estado || "activa";

  const fechaFormateada = (() => {
    try {
      const d = new Date(fecha);
      return d.toLocaleDateString("es-MX", {
        weekday: "long",
        year: "numeric",
        month: "long",
        day: "numeric",
      });
    } catch {
      return fecha;
    }
  })();

  const qrData = receta?.codigo_qr || `VITALIA-RECETA-${recetaId}`;
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  useEffect(() => {
    const cargar = async () => {
      try {
        setCargando(true);
        const res = await api.get(`/api/recetas/${recetaId}`);
        setReceta(res.data);
      } catch (e: any) {
        setError(e?.response?.data?.detail || "No se pudo cargar la receta.");
      } finally {
        setCargando(false);
      }
    };
    if (recetaId) cargar();
  }, [recetaId]);

  const items = receta?.items || [];

  // =========================================================
  // HTML DEL PDF (Con todos los datos clínicos nuevos)
  // =========================================================
  const generarHTML = () => {
    return `
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="utf-8" />
          <style>
            * { box-sizing: border-box; margin: 0; padding: 0; }
            body {
              font-family: 'Helvetica', Arial, sans-serif;
              color: #173F3A;
              padding: 40px;
              background-color: #FFFFFF;
              position: relative;
              min-height: 100vh;
            }
            
            /* MARCA DE AGUA (LOGO) */
            .watermark {
              position: fixed;
              top: 50%;
              left: 50%;
              transform: translate(-50%, -50%);
              width: 650px;
              height: auto;
              z-index: -1;
              opacity: 0.08;
              pointer-events: none;
            }

            /* ENCABEZADO */
            .header {
              display: flex;
              justify-content: space-between;
              align-items: center;
              border-bottom: 3px solid #0F766E;
              padding-bottom: 15px;
              margin-bottom: 25px;
            }
            .header-left img { height: 60px; }
            .header-left h1 { color: #0F766E; font-size: 24px; margin: 0; font-weight: 900; }
            .header-left p { color: #64748B; font-size: 10px; margin: 2px 0 0 0; }
            .header-right { text-align: right; }
            .header-right h2 { color: #173F3A; font-size: 16px; margin: 0; }
            .header-right p { color: #64748B; font-size: 11px; margin: 2px 0; }

            /* TARJETAS */
            .card {
              background: #F8FAFC;
              border: 1px solid #E2E8F0;
              border-radius: 10px;
              padding: 20px;
              margin-bottom: 20px;
              page-break-inside: avoid; /* 👈 ESTO EVITA QUE SE CORTE EN DOS PÁGINAS */
            }
/* 👇 NUEVO: Estilo específico para las indicaciones */
.indicaciones-text {
  font-size: 12px;
  color: #78350F;
  line-height: 1.6;
  white-space: pre-wrap; /* Respeta los saltos de línea que puso el doctor */
  padding: 0; /* Quita el padding que causa el espacio extra */
  margin: 0; /* Quita el margen superior que empuja el texto hacia abajo */
  text-align: left; /* Asegura que el texto esté a la izquierda */
}

          
            .card-title {
              font-size: 13px;
              font-weight: 800;
              color: #0F766E;
              text-transform: uppercase;
              letter-spacing: 1px;
              margin-bottom: 12px;
              border-bottom: 1px solid #E2E8F0;
              padding-bottom: 6px;
            }
            .info-grid {
              display: grid;
              grid-template-columns: 1fr 1fr;
              gap: 10px;
            }
            .info-item { font-size: 12px; }
            .info-item strong { color: #31534D; display: block; margin-bottom: 2px;}
            .info-item span { color: #173F3A; }

            /* MEDICAMENTOS */
            .medicamento {
              background: #FFFFFF;
              border-left: 4px solid #0F766E;
              border-radius: 6px;
              padding: 12px 16px;
              margin-bottom: 12px;
              box-shadow: 0 1px 2px rgba(0,0,0,0.05);
            }
            .med-nombre { font-size: 15px; font-weight: 800; color: #173F3A; margin-bottom: 6px; }
            .med-detalle { font-size: 12px; color: #4A5D59; margin: 3px 0; display: flex; align-items: center; }
            .med-detalle strong { color: #31534D; width: 90px; display: inline-block; }

            /* PIE DE PÁGINA Y FIRMA */
            .footer {
              margin-top: 40px;
              padding-top: 20px;
              border-top: 1px solid #DCEAE6;
              text-align: center;
              font-size: 10px;
              color: #82938F;
              display: flex;
              flex-direction: column;
              align-items: center;
            }
            .footer img { width: 110px; height: 110px; margin-bottom: 10px; }
            .firma-box {
              margin-top: 40px;
              display: flex;
              justify-content: center;
              align-items: center;
              flex-direction: column;
              border-top: 1px dashed #CBD5E1;
              padding-top: 10px;
              width: 250px;
              margin-left: auto;
              margin-right: auto;
            }
            .firma-box p { font-size: 12px; font-weight: 700; color: #31534D; margin-top: 5px;}
            .firma-box span { font-size: 10px; color: #64748B; }
          </style>
        </head>
        <body>
          <img class="watermark" src="${LOGO_MARCA_AGUA_BASE64}" alt="Marca de agua" />

          <div class="header">
            <div class="header-left">
              ${
                (LOGO_BASE64 as string) !==
                "data:image/png;base64,PEGA_AQUI_TU_LOGO_SUPERIOR"
                  ? `<img src="${LOGO_BASE64}" alt="VITALIA" />`
                  : `<h1>VITALIA</h1>`
              }
              <p>Tu salud, en buenas manos</p>
            </div>
            <div class="header-right">
              <h2>Receta Médica Oficial</h2>
              <p><strong>Folio:</strong> ${qrData}</p>
              <p><strong>Fecha:</strong> ${fechaFormateada}</p>
            </div>
          </div>

          <div class="card">
            <div class="card-title">Datos del Paciente y Médico</div>
            <div class="info-grid">
              <div class="info-item">
                <strong>Paciente</strong>
                <span>${paciente}</span>
              </div>
              <div class="info-item">
                <strong>Médico Tratante</strong>
                <span>Dr. ${doctor}</span>
              </div>
              <div class="info-item">
                <strong>Especialidad</strong>
                <span>${receta?.especialidad || "Medicina General"}</span>
              </div>
              <div class="info-item">
                <strong>Cédula / Licencia</strong>
                <span>${receta?.numero_licencia || "No registrada"}</span>
              </div>
              <!-- SIGNOS VITALES -->
                            
                            <!-- SIGNOS VITALES -->
              ${
                receta?.signos_vitales &&
                Object.keys(receta.signos_vitales).length > 0
                  ? `
                  <div class="info-item" style="grid-column: span 2; margin-top: 5px; background: #E7F5F2; padding: 8px; border-radius: 6px;">
                    <strong>Signos Vitales</strong>
                    <span style="font-size: 11px;">
                      ${Object.entries(receta.signos_vitales)
                        .filter(
                          ([_, valor]) =>
                            valor !== null &&
                            valor !== undefined &&
                            valor !== "",
                        )
                        .map(([key, valor]) => {
                          let etiqueta = key
                            .replace(/_/g, " ")
                            .replace(/\b\w/g, (l) => l.toUpperCase()); // Convierte "presion_arterial" a "Presion Arterial"
                          let sufijo = "";
                          if (key === "temperatura_c") {
                            etiqueta = "Temperatura";
                            sufijo = "°C";
                          }
                          if (key === "peso_kg") {
                            etiqueta = "Peso";
                            sufijo = " kg";
                          }
                          if (key === "talla_cm") {
                            etiqueta = "Talla";
                            sufijo = " cm";
                          }
                          if (key === "frecuencia_cardiaca") {
                            etiqueta = "Frec. Cardíaca";
                            sufijo = " lpm";
                          }
                          return `${etiqueta}: ${valor}${sufijo}`;
                        })
                        .join(" | ")}
                    </span>
                  </div>
                  `
                  : ""
              }
            </div>
          </div>

          <div class="card">
            <div class="card-title">Prescripción Médica</div>
            ${
              items.length === 0
                ? `<p style="font-size:13px;color:#82938F;font-style:italic;">Sin medicamentos registrados.</p>`
                : items
                    .map(
                      (it) => `
              <div class="medicamento">
                <div class="med-nombre">💊 ${it.medicamento ?? "Medicamento"} ${it.presentacion ? `(${it.presentacion})` : ""}</div>
                <div class="med-detalle"><strong>Dosis:</strong> <span>${it.dosis ?? "—"}</span></div>
                <div class="med-detalle"><strong>Frecuencia:</strong> <span>${it.frecuencia ?? "—"}</span></div>
                <div class="med-detalle"><strong>Duración:</strong> <span>${it.duracion ?? "—"}</span></div>
                <div class="med-detalle"><strong>Cantidad:</strong> <span>${it.cantidad ?? "—"} piezas</span></div>
                ${it.via_administracion ? `<div class="med-detalle"><strong>Vía:</strong> <span>${it.via_administracion}</span></div>` : ""}
                ${it.instrucciones ? `<div class="med-detalle"><strong>Instrucciones:</strong> <span>${it.instrucciones}</span></div>` : ""}
              </div>
            `,
                    )
                    .join("")
            }
          </div>
          <!-- RECUADRO DE INDICACIONES GENERALES -->
<div class="card" style="background: #FFFBEB; border-color: #FDE68A; page-break-inside: avoid; margin-top: 10px;">
  <div class="card-title" style="color: #92400E; border-bottom-color: #FDE68A; margin-bottom: 8px;">Indicaciones y Restricciones</div>
  <p class="indicaciones-text">
    ${receta?.indicaciones_generales ? receta.indicaciones_generales.trim() : "Sin indicaciones adicionales registradas. Siga las instrucciones de cada medicamento."}
  </p>
</div>

          <div class="firma-box">
            <p>Dr. ${doctor}</p>
            <span>Firma del Médico</span>
          </div>

          <div class="footer">
            <img src="${qrImageUrl}" alt="QR Receta" />
            <div>Documento generado electrónicamente por VITALIA.<br/>
            Escanee el código QR para validar la autenticidad de esta receta.<br/>
            <strong>Folio de validación:</strong> ${qrData}</div>
          </div>
        </body>
      </html>
    `;
  };

  const descargarPDF = async () => {
    setError("");
    setGenerandoPDF(true);
    const htmlReceta = generarHTML();

    try {
      if (Platform.OS === "web") {
        const win = window.open("", "_blank");
        if (!win) {
          setError("Habilita las ventanas emergentes para descargar el PDF.");
          return;
        }
        win.document.write(htmlReceta);
        win.document.close();
        win.focus();
        setTimeout(() => {
          win.print();
        }, 600);
      } else {
        const result: any = await Print.printToFileAsync({ html: htmlReceta });
        const uri = result?.uri;
        if (!uri) {
          setError("No se pudo generar el PDF.");
          return;
        }
        if (await Sharing.isAvailableAsync()) {
          await Sharing.shareAsync(uri, {
            mimeType: "application/pdf",
            dialogTitle: `Receta #${recetaId}`,
            UTI: "com.adobe.pdf",
          });
        } else {
          setError("Tu dispositivo no soporta compartir archivos.");
        }
      }
    } catch (e: any) {
      setError(e?.message || "No se pudo generar el PDF.");
    } finally {
      setGenerandoPDF(false);
    }
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      <View style={styles.header}>
        <Pressable
          style={styles.backButton}
          onPress={() => router.replace("/doctor/consultas")}
        >
          <Ionicons name="arrow-back" size={16} color={c.primary} />
          <Text style={styles.backText}>Volver al expediente</Text>
        </Pressable>
      </View>

      <Text style={styles.smallTitle}>RECETA MÉDICA OFICIAL</Text>
      <Text style={styles.title}>Receta #{recetaId}</Text>

      <View style={styles.card}>
        <Text style={styles.cardTitle}>Información de la receta</Text>
        <View style={styles.divider} />
        <Text style={styles.label}>Paciente:</Text>
        <Text style={styles.value}>{paciente}</Text>
        <Text style={styles.label}>Médico:</Text>
        <Text style={styles.value}>Dr. {doctor}</Text>
        <Text style={styles.label}>Fecha:</Text>
        <Text style={styles.value}>{fechaFormateada}</Text>
        <Text style={styles.label}>Estado:</Text>
        <Text
          style={[
            styles.value,
            { textTransform: "capitalize", color: c.primary },
          ]}
        >
          {estado}
        </Text>
      </View>

      <View style={styles.card}>
        <Text style={styles.cardTitle}>💊 Medicamentos</Text>
        <View style={styles.divider} />
        {cargando ? (
          <ActivityIndicator color={c.primary} />
        ) : items.length === 0 ? (
          <Text style={styles.vacio}>Sin medicamentos registrados.</Text>
        ) : (
          items.map((it) => (
            <View key={it.id_PK} style={styles.medBlock}>
              <Text style={styles.medTitle}>
                💊 {it.medicamento ?? "Medicamento"}{" "}
                {it.presentacion ? `(${it.presentacion})` : ""}
              </Text>
              {!!it.dosis && (
                <Text style={styles.medDetail}>
                  <Text style={styles.medLabel}>Dosis: </Text>
                  {it.dosis}
                </Text>
              )}
              {!!it.frecuencia && (
                <Text style={styles.medDetail}>
                  <Text style={styles.medLabel}>Frecuencia: </Text>
                  {it.frecuencia}
                </Text>
              )}
              {!!it.duracion && (
                <Text style={styles.medDetail}>
                  <Text style={styles.medLabel}>Duración: </Text>
                  {it.duracion}
                </Text>
              )}
              {!!it.cantidad && (
                <Text style={styles.medDetail}>
                  <Text style={styles.medLabel}>Cantidad: </Text>
                  {it.cantidad}
                </Text>
              )}
              {!!it.instrucciones && (
                <Text style={styles.medDetail}>
                  <Text style={styles.medLabel}>Instrucciones: </Text>
                  {it.instrucciones}
                </Text>
              )}
            </View>
          ))
        )}
      </View>

      <View
        style={[styles.card, { alignItems: "center", paddingVertical: 24 }]}
      >
        <Text style={styles.cardTitle}>Código QR de verificación</Text>
        <View style={styles.divider} />
        <View
          style={{
            backgroundColor: "#FFFFFF",
            padding: 20,
            borderRadius: 16,
            alignItems: "center",
          }}
        >
          <Text
            style={{
              fontSize: 14,
              fontWeight: "800",
              color: "#173F3A",
              marginBottom: 10,
            }}
          >
            RECETA MÉDICA
          </Text>
          <QRCode
            value={qrData}
            size={220}
            color="#173F3A"
            backgroundColor="#FFF"
          />
          <Text style={{ fontSize: 10, color: "#82938F", marginTop: 8 }}>
            VITALIA - Folio #{recetaId}
          </Text>
        </View>
        <Text style={styles.qrHelp}>{qrData}</Text>
        <Text style={styles.qrSubtext}>
          El farmacéutico escanea este código para verificar la receta.
        </Text>
      </View>

      {!!error && <Text style={styles.errorText}>{error}</Text>}

      <Pressable
        style={[styles.mainButton, generandoPDF && { opacity: 0.6 }]}
        onPress={descargarPDF}
        disabled={generandoPDF}
      >
        {generandoPDF ? (
          <ActivityIndicator color="#FFF" />
        ) : (
          <>
            <Ionicons name="document-text" size={20} color="#FFF" />
            <Text style={styles.mainButtonText}>Descargar Receta (PDF)</Text>
          </>
        )}
      </Pressable>

      <Pressable
        style={styles.secondaryButton}
        onPress={() => router.replace("/doctor/consultas")}
      >
        <Text style={styles.secondaryButtonText}>Cancelar</Text>
      </Pressable>
    </ScrollView>
  );
}

const createStyles = (c: Theme) => {
  const isDark = c.mode === "dark";
  return StyleSheet.create({
    container: { flex: 1, backgroundColor: c.bg },
    content: {
      padding: 24,
      maxWidth: 800,
      width: "100%",
      alignSelf: "center",
      paddingBottom: 50,
    },
    header: { marginBottom: 16 },
    backButton: {
      flexDirection: "row",
      alignItems: "center",
      alignSelf: "flex-start",
      paddingVertical: 8,
      paddingHorizontal: 12,
      backgroundColor: c.card,
      borderRadius: 10,
      borderWidth: 1,
      borderColor: c.border,
      gap: 6,
    },
    backText: { color: c.primary, fontSize: 13, fontWeight: "800" },
    smallTitle: {
      fontSize: 11,
      fontWeight: "800",
      letterSpacing: 2,
      color: c.primary,
      marginBottom: 5,
    },
    title: {
      fontSize: 28,
      fontWeight: "900",
      color: c.text,
      marginBottom: 20,
    },
    card: {
      backgroundColor: c.card,
      borderRadius: 16,
      padding: 20,
      borderWidth: 1,
      borderColor: c.border,
      marginBottom: 16,
    },
    cardTitle: {
      fontSize: 16,
      fontWeight: "800",
      color: c.text,
      marginBottom: 10,
    },
    divider: {
      height: 1,
      backgroundColor: isDark ? "rgba(255,255,255,0.08)" : "#EEF2F1",
      marginBottom: 12,
    },
    label: { fontSize: 12, fontWeight: "800", color: c.text, marginTop: 6 },
    value: { fontSize: 14, color: c.text, marginBottom: 2 },
    vacio: { fontSize: 13, color: c.muted, fontStyle: "italic" },
    medBlock: {
      backgroundColor: isDark ? "#1E2631" : "#F9FBFA",
      borderRadius: 10,
      padding: 12,
      marginBottom: 10,
      borderLeftWidth: 4,
      borderLeftColor: "#10B981",
    },
    medTitle: {
      fontSize: 15,
      fontWeight: "800",
      color: c.text,
      marginBottom: 6,
    },
    medDetail: { fontSize: 13, color: "#4A5D59", marginTop: 2 },
    medLabel: { fontWeight: "800", color: c.text },
    qrHelp: {
      fontSize: 11,
      color: c.text,
      fontWeight: "700",
      marginTop: 16,
      textAlign: "center",
    },
    qrSubtext: {
      fontSize: 11,
      color: c.muted,
      marginTop: 6,
      textAlign: "center",
      maxWidth: 280,
    },
    errorText: {
      color: "#B03A3A",
      fontSize: 13,
      fontWeight: "700",
      marginBottom: 12,
    },
    mainButton: {
      flexDirection: "row",
      justifyContent: "center",
      alignItems: "center",
      backgroundColor: c.primary,
      paddingVertical: 16,
      borderRadius: 12,
      gap: 8,
      marginTop: 8,
    },
    mainButtonText: { color: "#FFF", fontSize: 16, fontWeight: "800" },
    secondaryButton: {
      paddingVertical: 12,
      alignItems: "center",
      marginTop: 8,
    },
    secondaryButtonText: { color: c.muted, fontSize: 13, fontWeight: "700" },
  });
};
